const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}});
const form=document.querySelector('#enquiry');if(form){const comments=form.elements.Comments;comments.addEventListener('input',()=>document.querySelector('#count').textContent=comments.value.length);form.addEventListener('submit',e=>{e.preventDefault();const error=document.querySelector('#form-error');error.textContent='';document.querySelector('#form-status').textContent='';for(const el of form.querySelectorAll('[required]')){if((el.type==='checkbox'&&!el.checked)||(el.type!=='checkbox'&&!el.value.trim())){error.textContent=el.name==='consent'?'Please confirm consent to share your enquiry.':'Please complete '+el.name+'.';el.focus();return;}}if(!form.elements.Email.validity.valid){error.textContent='Please enter a valid email address.';form.elements.Email.focus();return;}if(!/^\+?[\d\s()\-]{7,22}$/.test(form.elements.Phone.value)||form.elements.Phone.value.replace(/\D/g,'').length<7){error.textContent='Please enter a valid phone number with at least 7 digits.';form.elements.Phone.focus();return;}const services=[...form.querySelectorAll('[name=service]:checked')].map(x=>x.value);if(!services.length){error.textContent='Please select at least one service.';const picker=form.querySelector('.service-picker');if(picker){picker.open=true;picker.querySelector('summary').focus();}else{form.querySelector('[name=service]').focus();}return;}const lines=['Hello RemapWorks UK, I would like a quote.',''];for(const name of ['Name','Email','Phone','Make','Model','Registration','Location'])lines.push(name+': '+(form.elements[name].value.trim()||'Not supplied'));lines.push('Services: '+services.join(', '),'Comments: '+(comments.value.trim()||'None'));const url='https://wa.me/447376668716?text='+encodeURIComponent(lines.join('\n'));window.open(url,'_blank','noopener,noreferrer');const status=document.querySelector('#form-status');status.textContent='Your message is ready. Review it and press Send in WhatsApp. If no window appeared, ';const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='open your prepared message here.';link.style.textDecoration='underline';status.append(link);});}
// Analytics intentionally disabled. Supply real IDs and implement appropriate consent before enabling tracking.
window.remapWorksTracking={gtmId:null,ga4Id:null,googleAdsId:null};

if(form){
 const picker=form.querySelector('.service-picker');
 if(picker){
  const selection=picker.querySelector('#service-selection');
  const summary=picker.querySelector('summary');
  const update=()=>{const chosen=[...picker.querySelectorAll('[name=service]:checked')];selection.textContent=chosen.length===0?'Select services':chosen.length===1?chosen[0].value:chosen.length+' services selected';};
  picker.addEventListener('change',update);
  picker.querySelector('.service-done').addEventListener('click',()=>{picker.open=false;summary.focus();});
  document.addEventListener('click',event=>{if(!picker.contains(event.target)&&!event.target.closest('button[type="submit"]'))picker.open=false;});
  picker.addEventListener('keydown',event=>{if(event.key==='Escape'){picker.open=false;summary.focus();}});
  update();
 }
}
